50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	import org.springframework.util.StringUtils;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Syntactic email validation: a non-empty local part and a dotted domain, with no whitespace.
68	     * Matches addresses such as {@code test.user@example.com} and rejects strings without an '@'
69	     * and a dotted domain (e.g. {@code not-an-email}).
70	     */
71	    private static final Pattern EMAIL_PATTERN = Pattern.compile(
72	        "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\\.[A-Za-z0-9!#$%&'*+/=?^_`{|}~-]+)*"
73	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?$");
74	
75	    /** Default country code assumed for national numbers that carry no explicit '+' prefix. */
76	    private static final String DEFAULT_COUNTRY_CODE = "61";
77	
78	    /** Separators (spaces, dashes and brackets) stripped from a telephone before parsing. */
79	    private static final Pattern TELEPHONE_SEPARATORS = Pattern.compile("[\\s()\\[\\]-]");
80	
81	    /** A valid E.164 body: a leading '+' followed by 8 to 15 digits. */
82	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
83	
84	    private final ClinicService clinicService;
85	
86	    private final OwnerMapper ownerMapper;
87	
88	    private final PetMapper petMapper;
89	
90	    private final VisitMapper visitMapper;
91	
92	    public OwnerRestControllerV1(ClinicService clinicService,
93	                                 OwnerMapper ownerMapper,
94	                                 PetMapper petMapper,
95	                                 VisitMapper visitMapper) {
96	        this.clinicService = clinicService;
97	        this.ownerMapper = ownerMapper;
98	        this.petMapper = petMapper;
99	        this.visitMapper = visitMapper;
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
105	        Collection<Owner> owners;
106	        if (lastName != null) {
107	            owners = this.clinicService.findOwnerByLastName(lastName);
108	        } else {
109	            owners = this.clinicService.findAllOwners();
110	        }
111	        if (owners.isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
120	        Owner owner = this.clinicService.findOwnerById(ownerId);
121	        if (owner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        List<String> missingFields = new ArrayList<>();
131	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
132	            missingFields.add("firstName");
133	        }
134	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
135	            missingFields.add("lastName");
136	        }
137	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
138	            missingFields.add("address");
139	        }
140	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
141	            missingFields.add("city");
142	        }
143	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
144	            missingFields.add("telephone");
145	        }
146	        if (!missingFields.isEmpty()) {
147	            throw new InvalidRequestException(missingFields);
148	        }
149	        HttpHeaders headers = new HttpHeaders();
150	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
151	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
152	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
153	        owner.setTelephone(normalizedTelephone);
154	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
155	        owner.setEmail(normalizeEmail(owner.getEmail()));
156	        // Default the (optional) registration date to the server's current date when none was supplied.
157	        if (owner.getRegistrationDate() == null) {
158	            owner.setRegistrationDate(LocalDate.now());
159	        }
160	        // Reject the request if the E.164 telephone is already used by another owner.
161	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
162	            throw new DuplicateTelephoneException(normalizedTelephone);
163	        }
164	        // Reject the request if another owner already shares the same last name and address
165	        // (compared case-insensitively with collapsed whitespace), unless the caller opts in
166	        // by setting 'sharesHousehold' true. When they do opt in and an existing household is
167	        // matched, assign a stable shared 'householdId' to the new owner and backfill it onto
168	        // every existing member that does not yet carry it.
169	        List<Owner> householdMembers = findHouseholdMembers(owner.getLastName(), owner.getAddress());
170	        if (!householdMembers.isEmpty()) {
171	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
172	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
173	            }
174	            String householdId = generateHouseholdId(owner.getLastName(), owner.getAddress());
175	            owner.setHouseholdId(householdId);
176	            for (Owner member : householdMembers) {
177	                if (!householdId.equals(member.getHouseholdId())) {
178	                    member.setHouseholdId(householdId);
179	                    this.clinicService.saveOwner(member);
180	                }
181	            }
182	        }
183	        // Assign the customer code '<LAST3>-<NNNN>' before persisting.
184	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
185	        this.clinicService.saveOwner(owner);
186	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
187	        headers.setLocation(UriComponentsBuilder.newInstance()
188	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
189	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
195	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
196	        if (currentOwner == null) {
197	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	        }
199	        currentOwner.setAddress(ownerFieldsDto.getAddress());
200	        currentOwner.setCity(ownerFieldsDto.getCity());
201	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
202	        currentOwner.setLastName(ownerFieldsDto.getLastName());
203	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
204	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
205	        this.clinicService.saveOwner(currentOwner);
206	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
207	    }
208	
209	    /**
210	     * Generate a customer code formatted {@code <LAST3>-<NNNN>}, where {@code LAST3} is the
211	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a global 4-digit
212	     * zero-padded sequence equal to one more than the current number of owners (e.g. {@code SMI-0007}).
213	     *
214	     * @param lastName the owner's last name
215	     * @return the generated customer code
216	     */
217	    private String generateCustomerCode(String lastName) {
218	        String prefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
219	        int sequence = this.clinicService.findAllOwners().size() + 1;
220	        return String.format("%s-%04d", prefix.toUpperCase(Locale.ROOT), sequence);
221	    }
222	
223	    /**
224	     * Find the existing owners that live in the same household as the given values, i.e. those that
225	     * share both the last name and the address when each is compared case-insensitively with
226	     * collapsed whitespace.
227	     *
228	     * @param lastName the incoming owner's last name
229	     * @param address  the incoming owner's address
230	     * @return the matching existing owners (possibly empty)
231	     */
232	    private List<Owner> findHouseholdMembers(String lastName, String address) {
233	        String normalizedLastName = normalizeForComparison(lastName);
234	        String normalizedAddress = normalizeForComparison(address);
235	        return this.clinicService.findAllOwners().stream()
236	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
237	                && normalizeForComparison(existing.getAddress()).equals(normalizedAddress))
238	            .toList();
239	    }
240	
241	    /**
242	     * Generate a stable shared household identifier for the given last name and address. The value is
243	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last name
244	     * and address, so every owner joining the same household resolves to the same identifier. It is the
245	     * first 12 upper-case hex characters of the SHA-256 digest of {@code <lastName>|<address>}.
246	     *
247	     * @param lastName the household's last name
248	     * @param address  the household's address
249	     * @return the stable household identifier
250	     */
251	    private String generateHouseholdId(String lastName, String address) {
252	        String key = normalizeForComparison(lastName) + "|" + normalizeForComparison(address);
253	        try {
254	            byte[] digest = MessageDigest.getInstance("SHA-256")
255	                .digest(key.getBytes(StandardCharsets.UTF_8));
256	            StringBuilder sb = new StringBuilder(digest.length * 2);
257	            for (byte b : digest) {
258	                sb.append(String.format("%02x", b));
259	            }
260	            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
261	        } catch (java.security.NoSuchAlgorithmException e) {
262	            throw new IllegalStateException("SHA-256 not available", e);
263	        }
264	    }
265	
266	    /**
267	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
268	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
269	     *
270	     * @param value the raw value, may be {@code null}
271	     * @return the normalized value
272	     */
273	    private String normalizeForComparison(String value) {
274	        if (value == null) {
275	            return "";
276	        }
277	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
278	    }
279	
280	    /**
281	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
282	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
283	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
284	     * is returned lower-cased.
285	     *
286	     * @param email the raw email from the request payload, may be {@code null}
287	     * @return the lower-cased email, or {@code null} when none was provided
288	     */
289	    private String normalizeEmail(String email) {
290	        if (!StringUtils.hasText(email)) {
291	            return null;
292	        }
293	        if (!EMAIL_PATTERN.matcher(email).matches()) {
294	            throw new InvalidRequestException(List.of("email"));
295	        }
296	        return email.toLowerCase(Locale.ROOT);
297	    }
298	
299	    /**
300	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
301	     * already carries a leading '+' keeps its country code; otherwise the default country code
302	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
303	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
304	     * is thrown (mapped to 400 Bad Request).
305	     *
306	     * @param telephone the raw telephone from the request payload
307	     * @return the E.164 string (e.g. {@code +61412345678})
308	     */
309	    private String normalizeTelephone(String telephone) {
310	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
311	        String candidate;
312	        if (cleaned.startsWith("+")) {
313	            candidate = cleaned;
314	        } else {
315	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
316	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
317	        }
318	        if (!E164_PATTERN.matcher(candidate).matches()) {
319	            throw new InvalidRequestException(List.of("telephone"));
320	        }
321	        return candidate;
322	    }
323	
324	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
325	    @Transactional
326	    @Override
327	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
328	        Owner owner = this.clinicService.findOwnerById(ownerId);
329	        if (owner == null) {
330	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
331	        }
332	        this.clinicService.deleteOwner(owner);
333	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
334	    }
335	
336	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
337	    @Override
338	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
339	        Owner owner = this.clinicService.findOwnerById(ownerId);
340	        if (owner == null) {
341	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
342	        }
343	        HttpHeaders headers = new HttpHeaders();
344	        Pet pet = petMapper.toPet(petFieldsDto);
345	        owner.setId(ownerId);
346	        pet.setOwner(owner);
347	        pet.getType().setName(null);
348	        this.clinicService.savePet(pet);
349	        PetDto petDto = petMapper.toPetDto(pet);
350	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
351	            .buildAndExpand(pet.getId()).toUri());
352	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
353	    }
354	
355	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
356	    @Override
357	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
358	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
359	        if (currentOwner != null) {
360	            Pet currentPet = this.clinicService.findPetById(petId);
361	            if (currentPet != null) {
362	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
363	                currentPet.setName(petFieldsDto.getName());
364	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
365	                this.clinicService.savePet(currentPet);
366	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
367	            }
368	        }
369	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
370	    }
371	
372	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
373	    @Override
374	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
375	        HttpHeaders headers = new HttpHeaders();
376	        Visit visit = visitMapper.toVisit(visitFieldsDto);
377	        Pet pet = new Pet();
378	        pet.setId(petId);
379	        visit.setPet(pet);
380	        this.clinicService.saveVisit(visit);
381	        VisitDto visitDto = visitMapper.toVisitDto(visit);
382	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
383	            .buildAndExpand(visit.getId()).toUri());
384	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
385	    }
386	
387	
388	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
389	    @Override
390	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
391	        Owner owner = this.clinicService.findOwnerById(ownerId);
392	        if (owner != null) {
393	            Pet pet = owner.getPet(petId);
394	            if (pet != null) {
395	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
396	            }
397	        }
398	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
399	    }
400	}
